declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\TenantLoginProviderMetadataVO;
use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\Holder\TenantLoginProviderMetadataAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantLoginProviderMetadataAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantLoginProviderMetadataAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that getMetadata returns null on a freshly created holder.
         */
        public function testMetadataNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithTenantLoginProviderMetadataAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isMetadataAssigned());
            $this->assertNull($holder->getMetadata());
        }
}
class ImplWithTenantLoginProviderMetadataAttributeHolderUnitTest
